/* Interactive proposal only: localStorage demo state, no real APIs or model calls. */
(() => {
  const el=id=>document.getElementById(id);
  const safe=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const key='crypto-prototype-settings-review-v1';
  const defaults={watch:['BTC','ETH','SOL'],xEnabled:true,accounts:['binance','brian_armstrong','coinbase','cz_binance','haydenzadams','okx','saylor','SECGov','VitalikButerin'].map(handle=>({handle,paused:false})),autoUpdate:true};
  let saved;try{saved=JSON.parse(localStorage.getItem(key))}catch{}
  let state=saved&&Array.isArray(saved.watch)&&Array.isArray(saved.accounts)?saved:structuredClone(defaults);
  let draft=state.watch.slice(),query='',active='watch';
  function persist(){try{localStorage.setItem(key,JSON.stringify(state));return true}catch{feedback('无法保存演示设置，请检查浏览器存储。',true);return false}}
  const sw=(id,label,on)=>`<button class="rv-switch" id="${id}" type="button" role="switch" aria-label="${label}" aria-checked="${on}"></button>`;
  document.body.insertAdjacentHTML('beforeend',`<dialog id="settings-review" aria-labelledby="rv-title">
    <div class="rv-head"><h2 id="rv-title">设置</h2><small>原型演示 · 不操作真实配置</small><button type="button" id="rv-close" aria-label="关闭设置">×</button></div>
    <div class="rv-layout"><nav class="rv-nav" role="tablist" aria-label="设置分类">${[['sources','信源'],['watch','关注币种'],['network','网络'],['system','系统'],['mcp','AI 与 MCP']].map(([id,label])=>`<button type="button" role="tab" id="rv-tab-${id}" data-rv-tab="${id}" aria-controls="rv-${id}" aria-selected="${id===active}">${label}</button>`).join('')}</nav>
    <div class="rv-content">
      <section class="rv-pane" id="rv-watch" role="tabpanel" aria-labelledby="rv-tab-watch"><h3>关注币种</h3><p class="rv-sub">已关注的币种始终显示在这里，可直接移除或添加。</p>
        <div class="rv-card"><div class="rv-line"><strong>已关注 <span id="rv-watch-count"></span></strong><span class="rv-grow"></span><span class="rv-muted" id="rv-dirty"></span></div><div class="rv-watch-list" id="rv-watch-list"></div>
          <form class="rv-add" id="rv-watch-add"><input id="rv-coin-input" aria-label="添加关注币种" placeholder="输入币种，如 DOGE、BNB" autocomplete="off"><button type="submit">添加关注</button></form>
          <p class="rv-feedback" id="rv-watch-feedback" role="status"></p><div class="rv-foot"><button type="button" id="rv-reset-watch">撤销本轮修改</button><span class="rv-grow"></span><button type="button" class="rv-primary" id="rv-save-watch">保存关注</button></div>
        </div><button type="button" id="rv-try-ai">试试通过对话说“关注 DOGE” →</button>
      </section>
      <section class="rv-pane" id="rv-sources" role="tabpanel" aria-labelledby="rv-tab-sources" hidden><h3>信源</h3><div class="rv-source-totals" id="rv-source-totals"></div>
        <div class="rv-card"><div class="rv-line"><strong>X 账号管理 <span class="rv-muted" id="rv-account-count"></span></strong><span class="rv-grow"></span><span class="rv-badge">已登录</span><a class="rv-x-open" id="rv-x-open" href="https://x.com/home" target="_blank" rel="noopener noreferrer" title="在浏览器中打开 X 首页">打开 X ↗</a><button type="button" id="rv-x-login">重新登录</button><span class="rv-muted">采集</span>${sw('rv-x-enabled','X账号采集',state.xEnabled)}</div>
          <p class="rv-note">浏览器：Edge · 登录状态与各账号的采集状态分开显示</p>
          <div class="rv-x-toolbar"><input class="rv-search" id="rv-x-search" type="search" aria-label="搜索X账号" placeholder="搜索已关注的账号"><form class="rv-add" id="rv-x-add"><input id="rv-x-input" aria-label="添加X账号" placeholder="输入 @账号" autocomplete="off"><button type="submit">添加账号</button></form></div>
          <div class="rv-x-accounts" id="rv-x-accounts" role="region" tabindex="0" aria-label="X关注账号列表"></div><div class="rv-scroll-note" id="rv-x-scroll" hidden>还有账号，向下滚动 ↓</div><p class="rv-feedback" id="rv-x-feedback" role="status"></p>
        </div><div class="rv-source-grid">${['CFTC 新闻稿','美联储 新闻稿','Bitcoin Magazine','CoinDesk','SEC 行政处罚','OKX 公告'].map(name=>`<div class="rv-card"><div class="rv-line"><strong>${name}</strong><span class="rv-grow"></span><span class="rv-badge ${name.startsWith('SEC')?'paused':''}">${name.startsWith('SEC')?'采集异常':'正常'}</span></div><p>${name.startsWith('SEC')?'需要配置联系邮箱':'每 5 分钟采集'}</p><button type="button" data-rv-demo="编辑信源">编辑</button><button type="button" data-rv-demo="暂停信源">暂停</button><button type="button" data-rv-demo="重试信源">立即重试</button></div>`).join('')}</div>
      </section>
      <section class="rv-pane" id="rv-network" role="tabpanel" aria-labelledby="rv-tab-network" hidden><h3>网络</h3><p class="rv-sub">管理所有外部请求的连接方式。</p><form class="rv-card rv-network" id="rv-network-form"><strong>连接方式</strong><label><input type="radio" name="rv-proxy" value="proxy" checked>使用代理</label><input type="text" id="rv-proxy-address" aria-label="代理地址" value="http://127.0.0.1:7890"><label><input type="radio" name="rv-proxy" value="direct">直连</label><div class="rv-foot"><button type="button" id="rv-test-network">测试连接</button><span class="rv-grow"></span><button type="submit" class="rv-primary">保存网络设置</button></div><p class="rv-feedback" id="rv-network-feedback" role="status"></p></form></section>
      <section class="rv-pane" id="rv-system" role="tabpanel" aria-labelledby="rv-tab-system" hidden><h3>系统</h3><p class="rv-sub">应用运行行为与版本更新。</p><div class="rv-card"><div class="rv-setting"><div><b>开机自启</b><small>登录系统后自动启动应用</small></div>${sw('rv-autostart','开机自启',false)}</div><div class="rv-setting"><div><b>关闭窗口时缩到托盘</b><small>保留后台采集和消息推送</small></div>${sw('rv-tray','关闭窗口时缩到托盘',true)}</div></div>
        <div class="rv-card"><div class="rv-line"><strong>应用更新</strong><span class="rv-grow"></span><span class="rv-muted">版本号为演示</span></div><div class="rv-setting"><div><b>自动检查更新</b><small>发现新版本后提示，安装前保留确认入口</small></div>${sw('rv-auto-update','自动检查更新',state.autoUpdate)}</div><div class="rv-foot"><span class="rv-muted" id="rv-update-status">当前版本 0.2.0（演示）</span><span class="rv-grow"></span><button type="button" id="rv-check-update">检查更新</button><button type="button" class="rv-primary" id="rv-install-update" hidden>安装更新</button></div></div>
      </section>
      <section class="rv-pane" id="rv-mcp" role="tabpanel" aria-labelledby="rv-tab-mcp" hidden><h3>AI 与 MCP</h3><p class="rv-sub">应用内 AI 与外部 MCP 客户端使用同一套工具与业务规则。</p><div class="rv-card"><div class="rv-line"><strong>MCP 接入</strong><span class="rv-grow"></span><span class="rv-badge paused">原型演示</span></div><p class="rv-note">本机 stdio · 外部 AI 客户端启动应用提供的 MCP 服务</p><pre class="rv-code">{"mcpServers":{"crypto-news":{"command":"安装目录/desktop.exe","args":["mcp"]}}}</pre><p class="rv-note">此为连接配置样式，实际命令和可用状态以实现后为准。</p><div class="rv-tool-grid"><span>信源与 X 账号管理</span><span>模型服务与用途配置</span><span>推送渠道与发送队列</span><span>关注币种与应用设置</span></div></div>
        <div class="rv-card"><strong>配置操作先确认</strong><p class="rv-note">查询直接返回。添加、修改、删除或发送先展示具体操作，确认后执行；应用内 AI 与外部 AI 使用相同规则。</p><button type="button" id="rv-try-source-ai" style="margin-top:12px">查看“添加信源”的对话预览 →</button></div>
      </section>
    </div></div></dialog>`);
  const dialog=el('settings-review');
  function selectTab(id){active=id;document.querySelectorAll('[data-rv-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.rvTab===id)));document.querySelectorAll('.rv-pane').forEach(p=>p.hidden=p.id!=='rv-'+id);el('rv-content')?.scrollTo(0,0);updateOverflow()}
  function feedback(text,bad=false){el('rv-watch-feedback').textContent=text;el('rv-watch-feedback').classList.toggle('error',bad)}
  function renderWatch(){const dirty=JSON.stringify(draft)!==JSON.stringify(state.watch);el('rv-watch-count').textContent=draft.length+' 个';el('rv-dirty').textContent=dirty?'有未保存修改':'';el('rv-save-watch').disabled=!dirty;el('rv-reset-watch').disabled=!dirty;el('rv-watch-list').innerHTML=draft.length?draft.map(a=>`<span class="rv-coin">${safe(a)}<button type="button" data-rv-remove="${safe(a)}" aria-label="移除关注 ${safe(a)}">×</button></span>`).join(''):'<span class="rv-muted">还没有关注币种，在下方添加。</span>'}
  function updateOverflow(){const list=el('rv-x-accounts');el('rv-x-scroll').hidden=list.scrollHeight-list.clientHeight-list.scrollTop<3}
  function renderAccounts(){const accounts=state.accounts.filter(a=>a.handle.toLowerCase().includes(query.toLowerCase().replace(/^@/,'')));el('rv-account-count').textContent=state.accounts.length+' 个账号';el('rv-x-accounts').innerHTML=accounts.length?accounts.map(a=>`<div class="rv-account"><div class="rv-account-main"><strong title="@${safe(a.handle)}">@${safe(a.handle)}</strong><small>${!state.xEnabled?'采集已关闭':a.paused?'已暂停':'采集正常'}</small></div><div class="rv-account-actions"><button type="button" data-rv-pause="${safe(a.handle)}" aria-label="${a.paused?'恢复':'暂停'}采集 @${safe(a.handle)}">${a.paused?'恢复':'暂停'}</button><button type="button" data-rv-delete="${safe(a.handle)}" aria-label="取消关注X账号 @${safe(a.handle)}">删除</button></div></div>`).join(''):`<p class="rv-note">${query?'没有匹配的账号。':'还没有关注账号，在上方添加。'}</p>`;const normal=state.xEnabled?state.accounts.filter(a=>!a.paused).length:0;el('rv-source-totals').innerHTML=`<span>信源 <b>${15+normal}/${18+state.accounts.length}</b> 正常</span><span>订阅/公告 <b>15/18</b> 正常</span><span>X 账号 <b>${normal}/${state.accounts.length}</b> 正常</span><span title="每个X账号独立计数；X管理面板不是单个信源">ⓘ</span>`;requestAnimationFrame(updateOverflow)}
  el('app-settings-open').onclick=()=>{draft=state.watch.slice();feedback('');renderWatch();renderAccounts();selectTab(active);dialog.showModal();requestAnimationFrame(updateOverflow)};
  el('rv-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
  document.querySelectorAll('[data-rv-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.rvTab));
  el('rv-watch-add').onsubmit=e=>{e.preventDefault();const input=el('rv-coin-input'),values=input.value.toUpperCase().split(/[\s,，]+/).filter(Boolean);if(!values.length)return feedback('请输入币种代码。',true);if(values.some(v=>!(/^[A-Z0-9]{1,12}$/).test(v)))return feedback('请输入字母或数字组成的币种代码。',true);const added=values.filter(v=>!draft.includes(v));if(!added.length)return feedback(values.join('、')+' 已在关注列表中。');const next=Array.from(new Set([...draft,...added]));if(next.length>20)return feedback('最多关注 20 个币种，请先移除一些。',true);draft=next;input.value='';renderWatch();feedback('已加入 '+added.join('、')+'，保存后生效。')};
  el('rv-watch-list').onclick=e=>{const b=e.target.closest('[data-rv-remove]');if(!b)return;draft=draft.filter(a=>a!==b.dataset.rvRemove);renderWatch();feedback('已移除 '+b.dataset.rvRemove+'，保存后生效。')};
  el('rv-reset-watch').onclick=()=>{draft=state.watch.slice();renderWatch();feedback('已撤销本轮修改。')};
  el('rv-save-watch').onclick=()=>{const old=state.watch;state.watch=draft.slice();if(!persist()){state.watch=old;return}renderWatch();feedback('关注列表已保存（仅本地原型）。')};
  el('rv-x-search').oninput=e=>{query=e.target.value;renderAccounts()};el('rv-x-accounts').onscroll=updateOverflow;window.addEventListener('resize',updateOverflow);
  el('rv-x-add').onsubmit=e=>{e.preventDefault();const input=el('rv-x-input'),handle=input.value.trim().replace(/^@/,'');if(!/^[A-Za-z0-9_]{1,15}$/.test(handle)){el('rv-x-feedback').textContent='请输入有效的 X 用户名。';return}if(state.accounts.some(a=>a.handle.toLowerCase()===handle.toLowerCase())){el('rv-x-feedback').textContent='该账号已经在关注列表中。';return}state.accounts.push({handle,paused:false});persist();input.value='';query='';el('rv-x-search').value='';renderAccounts();el('rv-x-feedback').textContent='已添加 @'+handle+'（演示）。'};
  el('rv-x-accounts').onclick=e=>{const pause=e.target.closest('[data-rv-pause]'),remove=e.target.closest('[data-rv-delete]');if(pause){const a=state.accounts.find(a=>a.handle===pause.dataset.rvPause);a.paused=!a.paused;persist();renderAccounts()}if(remove&&confirm('取消关注 @'+remove.dataset.rvDelete+'？仅修改原型演示数据。')){state.accounts=state.accounts.filter(a=>a.handle!==remove.dataset.rvDelete);persist();renderAccounts()}};
  dialog.querySelectorAll('.rv-switch').forEach(b=>b.onclick=()=>{const on=b.getAttribute('aria-checked')!=='true';b.setAttribute('aria-checked',String(on));if(b.id==='rv-x-enabled'){state.xEnabled=on;renderAccounts();persist()}if(b.id==='rv-auto-update'){state.autoUpdate=on;persist()}});
  el('rv-x-login').onclick=()=>el('rv-x-feedback').textContent='此处将打开 X 登录窗口，原型不调用真实浏览器。';
  el('rv-network-form').onsubmit=e=>{e.preventDefault();el('rv-network-feedback').textContent='网络设置已保存（演示，未改变真实代理）。'};
  el('rv-test-network').onclick=()=>el('rv-network-feedback').textContent='连接测试通过（演示结果，未发起网络请求）。';
  el('rv-check-update').onclick=()=>{el('rv-update-status').textContent='发现新版本 0.2.1（演示）';el('rv-install-update').hidden=false};
  el('rv-install-update').onclick=()=>{el('rv-update-status').textContent='此处将确认安装并重启应用，原型不安装真实更新。'};
  dialog.querySelectorAll('[data-rv-demo]').forEach(b=>b.onclick=()=>notify(b.dataset.rvDemo+'：交互占位，未改变真实设置'));
  const plans=new Map();let planId=0;
  window.protoOperationCard=m=>`<div class="rv-plan"><h4>${m.status==='done'?'操作已完成（演示）':m.status==='cancelled'?'操作已取消':'待确认的配置操作'}</h4><dl><dt>操作</dt><dd>${safe(m.kind==='watch'?'添加关注币种':'添加 RSS 信源')}</dd><dt>${m.kind==='watch'?'币种':'名称'}</dt><dd>${safe(m.value)}</dd>${m.kind==='source'?'<dt>地址</dt><dd>https://example.org/feed.xml</dd>':''}</dl>${m.status==='pending'?`<div class="rv-foot"><button type="button" data-rv-plan-cancel="${m.planId}">取消</button><span class="rv-grow"></span><button type="button" class="rv-primary" data-rv-plan-confirm="${m.planId}">确认执行</button></div><small>确认前不会修改配置。应用内与外部 AI 使用同一套 MCP 操作规则。</small>`:'<small>'+safe(m.status==='done'?'已更新原型演示状态，不调用真实 MCP 或模型。':'未执行任何配置变更。')+'</small>'}</div>`;
  const previousSend=sendQuestion;
  sendQuestion=function(q,context){const watch=/关注\s+([A-Za-z0-9]{1,12})\b/i.exec(q),source=/添加.*信源|添加.*RSS/i.test(q);if(!watch&&!source)return previousSend(q,context);const s=session();s.msgs.push({type:'question',text:q,contexts:[]});const m={type:'operation',kind:watch?'watch':'source',value:watch?watch[1].toUpperCase():'示例资讯源',planId:++planId,status:'pending',text:''};plans.set(m.planId,m);s.msgs.push(m);el('question').value='';renderChat(true)};
  document.addEventListener('click',e=>{const confirmButton=e.target.closest('[data-rv-plan-confirm]'),cancelButton=e.target.closest('[data-rv-plan-cancel]');if(!confirmButton&&!cancelButton)return;const m=plans.get(Number((confirmButton||cancelButton).dataset[confirmButton?'rvPlanConfirm':'rvPlanCancel']));if(!m||m.status!=='pending')return;m.status=confirmButton?'done':'cancelled';if(confirmButton&&m.kind==='watch'){state.watch=Array.from(new Set([...state.watch,m.value]));draft=state.watch.slice();persist();renderWatch()}renderChat(true)});
  function tryAI(question){dialog.close();document.getElementById('shell').dispatchEvent(new Event('expand-chat'));sendQuestion(question)}
  el('rv-try-ai').onclick=()=>tryAI('关注 DOGE');el('rv-try-source-ai').onclick=()=>tryAI('添加一个 RSS 信源，名称是示例资讯源，地址是 https://example.org/feed.xml');
  renderWatch();renderAccounts();
})();
